if(!exists('validate_source_lineage',mode='function'))library(creditratingsystem)
ids<-c('z','ä','A','a','Ω','Z');rows<-lapply(ids,function(i)list(record_id=i,join_key=i,weight=1,amounts=list(balance=1)))
node<-list(node_id='n',kind='SOURCE',schema_version='1',vintage='2024',revision='1',transformation_version='identity',content_hash=paste(rep('a',64),collapse=''),observed_at='2024-01-01',available_at='2024-01-01',source_id='s',semantic_role='FEATURE',records=rows)
kw<-list(nodes=list(node),edges=list(),joins=list(),reconciliations=list(list(reconciliation_id='c',node_id='n',reference='independent-control',expected_record_ids=as.list(ids),expected_total_weight=6,expected_amounts=list(balance=6))),uses=list(list(use_id='u',node_id='n',purpose='FEATURE',as_of='2024-01-01',known_at='2024-01-01',source_snapshot_hashes=list(n=node$content_hash))),contract=list(contract_id='c',version='1',reference='canonical-ids',amount_fields=list(balance='EUR'),absolute_tolerance=0,relative_tolerance=0,required_node_ids=list('n'),required_use_ids=list('u'),required_join_ids=list()))
first<-do.call(validate_source_lineage,kw)$value;kw$nodes[[1]]$records<-rev(kw$nodes[[1]]$records);second<-do.call(validate_source_lineage,kw)$value
stopifnot(first$decision$status=='PASS',second$decision$status=='PASS',identical(first$node_totals,second$node_totals),identical(unlist(first$node_totals$n$record_ids),c('A','Z','a','z','ä','Ω')))
